//! Lots and the stock that holds them.

use std::cell::RefCell;
use std::collections::BTreeMap;
use std::rc::Rc;

use super::journal::{Entry, Journal};

/// The days after its opening day that an opened lot can still be used.
const OPEN_SPAN: u64 = 30;

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Lot {
    pub id: u32,
    pub item: String,
    pub mg: u64,
    pub best_before: Option<u32>,
    pub received: u32,
}

/// The place of a lot in the order of use, compared field by field: lots with a
/// best-before day first, by that day, then by the day received; lots without one
/// last, by the day received.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub struct UseKey {
    keeps: bool,
    best_before: u32,
    received: u32,
}

impl Lot {
    pub fn use_key(&self) -> UseKey {
        UseKey {
            keeps: self.best_before.is_none(),
            best_before: self.best_before.unwrap_or(0),
            received: self.received,
        }
    }

    /// Whether the best-before day allows using the lot on a day.
    fn fresh_on(&self, day: u32) -> bool {
        self.best_before.map_or(true, |best_before| day <= best_before)
    }
}

/// One take that a pick keeps, in the order taken.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct Taken {
    pick: u32,
    day: u32,
    lot: u32,
}

#[derive(Debug)]
pub struct Stock {
    lots: Vec<Lot>,
    following_pick: u32,
    broached: BTreeMap<u32, u32>,
    history: Vec<Taken>,
    journal: Rc<RefCell<Journal>>,
}

impl Clone for Stock {
    /// A copy with a journal of its own.
    fn clone(&self) -> Stock {
        Stock {
            lots: self.lots.clone(),
            following_pick: self.following_pick,
            broached: self.broached.clone(),
            history: self.history.clone(),
            journal: Rc::new(RefCell::new(self.journal.borrow().clone())),
        }
    }
}

impl Default for Stock {
    fn default() -> Stock {
        Stock::new()
    }
}

impl Stock {
    pub fn new() -> Stock {
        Stock {
            lots: Vec::new(),
            following_pick: 1,
            broached: BTreeMap::new(),
            history: Vec::new(),
            journal: Rc::new(RefCell::new(Journal::default())),
        }
    }

    pub fn receive(&mut self, lot: Lot) {
        self.lots.push(lot);
    }

    pub fn lots(&self) -> &[Lot] {
        &self.lots
    }

    pub fn journal(&self) -> Rc<RefCell<Journal>> {
        Rc::clone(&self.journal)
    }

    pub fn carries(&self, item: &str) -> bool {
        self.lots.iter().any(|lot| lot.item == item)
    }

    pub fn on_hand(&self, item: &str) -> u64 {
        self.lots
            .iter()
            .filter(|lot| lot.item == item)
            .map(|lot| lot.mg)
            .sum()
    }

    /// Whether a lot's opening still allows using it on a day.
    fn open_on(&self, lot: &Lot, day: u32) -> bool {
        self.broached
            .get(&lot.id)
            .map_or(true, |&broached| u64::from(day) <= u64::from(broached) + OPEN_SPAN)
    }

    /// The lots of an item that can be used on a day, in the order of use.
    pub fn available(&self, item: &str, day: u32) -> Vec<Lot> {
        let mut lots: Vec<Lot> = self
            .lots
            .iter()
            .filter(|lot| lot.item == item && lot.fresh_on(day) && self.open_on(lot, day))
            .cloned()
            .collect();
        lots.sort_by_key(Lot::use_key);
        lots
    }

    pub fn following_pick(&mut self) -> u32 {
        let number = self.following_pick;
        self.following_pick += 1;
        number
    }

    /// Takes from a lot and records the take in the journal.
    pub fn take(&mut self, pick: u32, day: u32, lot: u32, mg: u64) {
        let target = self
            .lots
            .iter_mut()
            .find(|target| target.id == lot)
            .expect("a lot of this stock");
        assert!(target.mg >= mg, "a take within what the lot holds");
        target.mg -= mg;
        let item = target.item.clone();
        self.broached.entry(lot).or_insert(day);
        self.history.push(Taken { pick, day, lot });
        self.journal.borrow_mut().log_take(Entry { pick, day, lot, item, mg });
    }

    /// Puts what a take took back into its lot.
    pub fn hand_back(&mut self, lot: u32, mg: u64) {
        let target = self
            .lots
            .iter_mut()
            .find(|target| target.id == lot)
            .expect("a lot of this stock");
        target.mg += mg;
    }

    /// Forgets the takes of a pick taken back: each lot it touched counts as
    /// opened by the first take from it that another pick keeps, or not opened.
    pub fn forget_pick(&mut self, pick: u32) {
        let touched: Vec<u32> = self
            .history
            .iter()
            .filter(|taken| taken.pick == pick)
            .map(|taken| taken.lot)
            .collect();
        self.history.retain(|taken| taken.pick != pick);
        for lot in touched {
            match self.history.iter().find(|taken| taken.lot == lot) {
                Some(first) => {
                    self.broached.insert(lot, first.day);
                }
                None => {
                    self.broached.remove(&lot);
                }
            }
        }
    }

    /// Makes the books read as a saved copy does, keeping this stock's journal
    /// handle so that reporters made from it see the restored journal.
    pub fn restore(&mut self, saved: Stock) {
        let journal = saved.journal.borrow().clone();
        *self.journal.borrow_mut() = journal;
        self.lots = saved.lots;
        self.following_pick = saved.following_pick;
        self.broached = saved.broached;
        self.history = saved.history;
    }

    pub fn flush(&mut self) -> Vec<Entry> {
        self.journal.borrow_mut().hand_off()
    }
}

//! Orders: what they ask for and how they are filled from the lots.

use std::collections::BTreeMap;

use super::lots::Stock;

/// A line of an order.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Line {
    pub item: String,
    pub mg: u64,
}

/// What a line takes from one lot.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Take {
    pub line: usize,
    pub lot: u32,
    pub mg: u64,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Pick {
    pub number: u32,
    pub takes: Vec<Take>,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Refusal {
    UnknownItem { line: usize },
    Short { line: usize, missing: u64 },
}

/// Fills an order, all of it or nothing.
pub fn fill(stock: &mut Stock, day: u32, lines: &[Line]) -> Result<Pick, Refusal> {
    let mut takes = Vec::new();
    // What the earlier lines of this order take from each lot.
    let mut planned: BTreeMap<u32, u64> = BTreeMap::new();
    for (index, line) in lines.iter().enumerate() {
        if !stock.carries(&line.item) {
            return Err(Refusal::UnknownItem { line: index });
        }
        let mut left = line.mg;
        let mut line_takes = Vec::new();
        for lot in stock.available(&line.item, day) {
            if left == 0 {
                break;
            }
            let used = planned.get(&lot.id).copied().unwrap_or(0);
            let mg = left.min(lot.mg - used);
            if mg > 0 {
                line_takes.push(Take { line: index, lot: lot.id, mg });
                left -= mg;
            }
        }
        if left > 0 {
            return Err(Refusal::Short { line: index, missing: left });
        }
        for take in line_takes {
            *planned.entry(take.lot).or_insert(0) += take.mg;
            takes.push(take);
        }
    }
    let number = stock.following_pick();
    for take in &takes {
        stock.take(number, day, take.lot, take.mg);
    }
    Ok(Pick { number, takes })
}

/// Fills every order of a batch, or none of them.
pub fn fill_all(
    stock: &mut Stock,
    orders: &[(u32, Vec<Line>)],
) -> Result<Vec<Pick>, (usize, Refusal)> {
    let saved = stock.clone();
    let mut picks = Vec::new();
    for (index, (day, lines)) in orders.iter().enumerate() {
        match fill(stock, *day, lines) {
            Ok(pick) => picks.push(pick),
            Err(refusal) => {
                stock.restore(saved);
                return Err((index, refusal));
            }
        }
    }
    Ok(picks)
}

/// Takes back a pick whose entries wait in the journal.
pub fn take_back(stock: &mut Stock, number: u32) -> Result<(), u32> {
    let gone = stock.journal().borrow_mut().remove(number);
    if gone.is_empty() {
        return Err(number);
    }
    for entry in &gone {
        stock.hand_back(entry.lot, entry.mg);
    }
    stock.forget_pick(number);
    Ok(())
}

//! The journal: what left the stock and has not been written out yet.

use std::collections::BTreeMap;

/// One take from one lot.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Entry {
    pub pick: u32,
    pub day: u32,
    pub lot: u32,
    pub item: String,
    pub mg: u64,
}

#[derive(Clone, Debug, Default)]
pub struct Journal {
    entries: Vec<Entry>,
    moved: BTreeMap<String, u64>,
}

impl Journal {
    pub fn log_take(&mut self, entry: Entry) {
        *self.moved.entry(entry.item.clone()).or_insert(0) += entry.mg;
        self.entries.push(entry);
    }

    pub fn entries(&self) -> &[Entry] {
        &self.entries
    }

    /// What left the stock so far, by item, written out or not.
    pub fn moved(&self) -> &BTreeMap<String, u64> {
        &self.moved
    }

    /// Takes a pick's entries out of the journal and returns them; what they
    /// moved no longer counts as having left the stock.
    pub fn remove(&mut self, pick: u32) -> Vec<Entry> {
        let (gone, kept): (Vec<Entry>, Vec<Entry>) = std::mem::take(&mut self.entries)
            .into_iter()
            .partition(|entry| entry.pick == pick);
        self.entries = kept;
        for entry in &gone {
            if let Some(moved) = self.moved.get_mut(&entry.item) {
                *moved -= entry.mg;
                if *moved == 0 {
                    self.moved.remove(&entry.item);
                }
            }
        }
        gone
    }

    /// Hands the entries over to be written out.
    pub fn hand_off(&mut self) -> Vec<Entry> {
        std::mem::take(&mut self.entries)
    }
}
